import { Component } from '@angular/core';
import { Pienso } from 'src/app/models/pienso';
import { PiensoService } from 'src/app/services/pienso.service';

@Component({
  selector: 'app-categorias',
  templateUrl: './categorias.component.html',
  styleUrls: ['./categorias.component.css']
})
export class CategoriasComponent {


  //CATEGORIAS FILTROS PIENSOS
  constructor(private piensoService: PiensoService){}


  //BOTON VER TODOS LOS PRODUCTOS
  mostrarTodosLosProductos() {
    this.piensoService.getPiensos().subscribe(
      piensos => {
        this.piensoService.piensos = piensos;
      },
      error => {
        console.error('Error al obtener todos los productos', error);
      }
    );
  }


  //Es un metodo que le pasas el tipo de animal como parametro y te busca lo que le pidas
  filtrarPorTipo(tipoAnimal: string) {
    this.piensoService.getPiensosPorTipo(tipoAnimal).subscribe( //te busca los piensos del animal que introduzcas por paramtero
      piensos => {
        this.piensoService.piensos = piensos; //muestra los piensos
      }
    );
  }


  //POR PRECIO
  filtrarPorPrecio(rangoPrecio: string) {
    this.piensoService.getPiensosPorPrecio(rangoPrecio).subscribe(
      piensos => {
        this.piensoService.piensos = piensos;
      }
    );
  }

  //POR PESOS
  filtrarPorPeso(rangoPeso: string) {
    this.piensoService.getPiensosPorPeso(rangoPeso).subscribe(
      piensos => {
        this.piensoService.piensos = piensos;
      }
    );
  }

}
<!--TODOS LOS PRODUCTOS-->
<br>

<li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em; margin-left: 13px;">Todos</li>

<li class="list-group-item">
  <a (click)="mostrarTodosLosProductos()" style="text-decoration: none; cursor: pointer; color: blue; margin-left: 15px;">Ver todos los productos</a>
</li>


<ul class="list-group list-group-flush" style="margin-bottom: 7%;">
  <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em; ">Perros</li>

  <!--FILTROS PIENSOS PERROS-->
    <li class="list-group-item">
      <a (click)="filtrarPorTipo('Perro')" style="text-decoration: none; cursor: pointer; color: blue;">Comida para perros</a>
    </li>

    <li class="list-group-item"> <a href="#" style="text-decoration: none; color: blue;"> Juguetes para perros </a></li>

</ul>



<ul class="list-group list-group-flush">
    <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;">Gatos</li>

    <!--FILTROS PIENSOS GATOS-->
    <li class="list-group-item">
      <a (click)="filtrarPorTipo('Gato')" style="text-decoration: none; cursor: pointer; color: blue;">Comida para gatos</a>
    </li>

    <li class="list-group-item"> <a href="#" style="text-decoration: none; color: blue;">Juguetes para gatos</a></li>
</ul>



    <!--BOTONES DE PRECIO-->
    <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;margin-left: 13px;">Precios</li>

    <!-- Input de Rango de Precios Personalizado
    <div style="display: flex; align-items: center; margin-bottom: 15px;">
      <input type="text" placeholder="Mín" style="margin-right: 5px; width: 50px; font-size: 14px;"/>
      <span>-</span>
      <input type="text" placeholder="Máx" style="margin-left: 5px; width: 50px; font-size: 14px; margin-right: 10px;"/>
      <button type="button" class="btn btn-primary">Buscar</button>
    </div>-->


    <div class="form-check">
      <input type="checkbox" id="precio1" name="grupo1" (click)="filtrarPorPrecio('0-10')">
      <label class="form-check-label" for="Precios"> 0 - 10</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio2" name="grupo1" (click)="filtrarPorPrecio('11-20')">
      <label class="form-check-label" for="Precios"> 11 - 20</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio3" name="grupo1" (click)="filtrarPorPrecio('21-30')">
      <label class="form-check-label" for="Precios"> 21 - 30</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio4" name="grupo1" (click)="filtrarPorPrecio('31-40')">
      <label class="form-check-label" for="Precios"> 31 - 40</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio5" name="grupo1" (click)="filtrarPorPrecio('41-50')">
      <label class="form-check-label" for="Precios"> 41 - 50</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio6" name="grupo1" (click)="filtrarPorPrecio('51-60')">
      <label class="form-check-label" for="Precios"> 51 - 60</label>
    </div>



    <!--BOTONES DE PESO-->
    <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em; margin-left: 13px;">Peso</li>


    <!-- Input de Rango de Peso Personalizado
    <div style="display: flex; align-items: center; margin-bottom: 15px;">
      <input type="text" placeholder="Mín" style="margin-right: 5px; width: 50px; font-size: 14px;"/>
      <span>-</span>
      <input type="text" placeholder="Máx" style="margin-left: 5px; width: 50px; font-size: 14px; margin-right: 10px;"/>
      <button type="button" class="btn btn-primary">Buscar</button>
    </div>-->


    <div class="form-check">
      <input type="checkbox" id="peso1" name="grupo2" (click)="filtrarPorPeso('0-5')">
      <label class="form-check-label" for="Peso">0 - 5</label>
    </div>

    <div class="form-check">
      <input type="checkbox" id="peso2" name="grupo2" (click)="filtrarPorPeso('6-10')">
      <label class="form-check-label" for="Peso">6 - 10</label>
    </div>

    <div class="form-check">
      <input type="checkbox" id="peso3" name="grupo2" (click)="filtrarPorPeso('11-15')">
      <label class="form-check-label" for="Peso">11 - 15</label>
    </div>

    <div class="form-check">
      <input type="checkbox" id="peso4" name="grupo2" (click)="filtrarPorPeso('16-20')">
      <label class="form-check-label" for="Peso">16 - 20</label>
    </div>

    <div class="form-check">
      <input type="checkbox" id="peso5" name="grupo2" (click)="filtrarPorPeso('21-25')">
      <label class="form-check-label" for="Peso">21 - 25</label>
    </div>


    <br>

    <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;margin-left: 13px;">Buscar por tipo de edad</li>


    <!--CHECKBOX DE JUNIOR, ADULTO Y SENIOR-->

    <div class="form-check">
      <input type="checkbox" id="edad1" name="grupo3">
      <label class="form-check-label" for="Edad"  style="margin-left: 10px;">Junior</label>
    </div>

    <div class="form-check">
      <input type="checkbox" id="edad2" name="grupo3">
      <label class="form-check-label" for="Edad" style="margin-left: 10px;">Adulto</label>
    </div>

    <div class="form-check">
      <input type="checkbox" id="edad3" name="grupo3">
      <label class="form-check-label" for="Edad"  style="margin-left: 10px;">Senior</label>
    </div>
